By the commutativity of the diagram
$$
\begin{CD}
H(e_1) & @>>> &H({\mathbf e}_1)\\
@VVV & & @VVV\\
H(\hat e_1) &@>>> &H(\hat{\mathbf e}_1)\;,
\end{CD}
$$
where all maps are canonical, the result follows directly from Theorem~\ref{t:H1}-(vii),
Corollaries~\ref{c:H(hate1)=H(hatbfe1)} and~\ref{c:H(bfe_1)=H(hatbfe_1)}.

>From Lemma~\ref{l:decomposition of calAr} we get a (non-canonical) isomorphism
\begin{equation}\label{e:A/ker d}
\frac{\text{$\mathcal{A}$}^r}{\text{$\mathcal{A}$}^r\cap\ker d}
\cong\bigoplus_\ell\frac{E_\ell^r}{E_\ell^r\cap\ker d_\ell}\;,
\end{equation}
Then let $L_k^{u,v}$ be the subspace of $\text{$\mathcal{A}$}^r/(\text{$\mathcal{A}$}^r\cap\ker d)$ that corresponds to
$$
\bigoplus_{l\geq k}\frac{E_\ell^{u,v}}{E_\ell^{u,v}\cap\ker d_\ell}
$$
by \eqref{e:A/ker d}. Then property~(i) easily follows from Lemma~\ref{l:decomposition of calAr}, and
property~(ii) is obvious; in fact, $L_k^r$ corresponds to
$$
\bigoplus_{l\geq k}\frac{E_\ell^r}{E_\ell^r\cap\ker d_\ell}
$$
by \eqref{e:A/ker d}.

\label{claim:frakH2} 
A differential form $\omega\in\Omega$ is in ${\mathfrak H}_2$ if and only if it has extensions
$\tilde\omega_1(h),\tilde\omega_2(h)\in\Omega[h]$ satisfying
\begin{equation}\label{e:frakH2}
d_h\tilde\omega_1(h)\in h^2\Omega[h]\;,\quad\delta_h\tilde\omega_2(h)\in h^2\Omega[h]\;.
\end{equation}

\label{asymptotics of eigenforms}
For any Riemannian foliation on a closed manifold with a bundle-like metric, let $\omega_i$ be a sequence in
$\Omega^r$ such that $\|\omega_i\|=1$ and
\begin{equation}\label{e:asymptotics of eigenforms}
\left\langle\Delta_{h_i}\omega_i,\omega_i\right\rangle\in o\big(h_i^{2(k-1)}\big)
\end{equation}
for some fixed integer $k\ge1$ and some sequence $h_i\downarrow0$. Then,  if $k\geq2$ {\rm(}resp. $k=1${\rm)}, some subsequence of $\omega_i$ is strongly {\rm(}resp., weakly {\rm)} convergent in $\boldsymbol{\Omega}$, and its limit is in $\mathcal{H}_k^r$ {\rm(}resp., $L^2\mathcal{H}_1^r${\rm)}.
